-- Nickname filter (generated by tools/gen-nick-sql.js from js/nickfilter.js: do not edit by hand).
-- Run once in the Supabase SQL editor. After it, the database refuses offensive names, links, e-mails and phone numbers
-- in players.nick (multiplayer rooms) and quietly shows "Player" for them on the league board, even when the page is bypassed.

create or replace function public.tpk_nick_check(p text) returns text
language plpgsql immutable set search_path = public as $$
declare
  raw text; v text; flat text; tok text; run text := ''; toks text[]; outt text[] := '{}'; part text;
begin
  raw := lower(regexp_replace(btrim(coalesce(p, '')), '[\u200b-\u200f\u2028-\u202f\u2060\ufeff]', '', 'g'));
  raw := regexp_replace(raw, '\s+', ' ', 'g');
  if raw = '' then return ''; end if;
  if raw ~ 'https?:|www\.|[a-z0-9]@[a-z0-9]|\.(com|net|org|fr|es|io|eu|co|me|ly|gg|tv|xyz|app|link|ru|cn)([^a-z]|$)' or raw ~ '[0-9]([ .-]?[0-9]){6,}' then return 'link'; end if;
  v := translate(raw, 'àáâãäåçèéêëìíîïñòóôõöùúûüýÿ', 'aaaaaaceeeeiiiinooooouuuuyy');
  v := replace(replace(replace(replace(v, 'ß', 'ss'), 'ø', 'o'), 'æ', 'ae'), 'œ', 'oe');
  v := translate(v, '013457@$!+|€£аеосрхі', 'oieastasitieeaeocpxi');
  flat := regexp_replace(v, '[^a-z0-9ㄱ-ㆎ가-힣]+', '', 'g');
  if flat ~ '시발|씨발|씨바|씹|개새끼|개색|새끼|병신|븅신|좆|존나|지랄|느금마|니애미|보지|자지|창녀|걸레|미친놈|미친년|닥쳐|꺼져|한남충|김치녀|일베|짱깨|쪽바리|틀딱|ㅅㅂ|ㅆㅂ|ㅂㅅ|ㅄ|ㅈㄹ|ㅈㄴ|ㄲㅈ|ㅁㅊ' then return 'bad'; end if;
  toks := array_remove(regexp_split_to_array(v, '[^a-z0-9ㄱ-ㆎ가-힣]+'), '');
  foreach tok in array coalesce(toks, '{}') loop
    part := tok;
    part := replace(part, 'shiitake', ' ');
    part := replace(part, 'shitake', ' ');
    part := replace(part, 'shitzu', ' ');
    part := replace(part, 'shihtzu', ' ');
    outt := outt || array_remove(string_to_array(part, ' '), '');
    if length(tok) = 1 then run := run || tok;
    else
      if length(run) > 1 then outt := outt || run; end if;
      run := '';
    end if;
  end loop;
  if length(run) > 1 then outt := outt || run; end if;
  foreach tok in array outt loop
    if tok ~ '^(?:a+s{2,}|a+r+s+e+|a+s{2,}h+a+t+|c+o+c+k+|c+o+c+k+s+|c+u+n+t+|c+u+m+|t+w+a+t+|p+r+i+c+k+|p+u+s{2,}y+|w+h+o+r+e+|s+l+u+t+|f+a+g+|f+a+g{2,}o+t+|t+r+a+n{2,}y+|s+h+e+m+a+l+e+|c+h+i+n+k+|g+o{2,}k+|s+p+i+c+|c+o{2,}n+|p+a+k+i+|w+e+t+b+a+c+k+|n+a+z+i+|n+a+z+i+s+|k{3,}|r+a+p+e+|r+a+p+e+d+|r+a+p+i+s+t+|p+o+r+n+|p+e+d+o+|k+y+s+|w+a+n+k+|w+a+n+k+e+r+|d+i+l+d+o+|p+e+n+i+s+|v+a+g+i+n+a+|a+n+u+s+|t+i+t+s+|t+i+t{2,}y+|b+o{2,}b+s+|j+i+z{2,}|c+o+n{2,}e+|c+o+n{2,}a+r+d+|c+o+n{2,}a+s{2,}e+|p+u+t+e+|p+u+t+e+s+|p+u+t+a+i+n+|s+a+l+o+p+e+|s+a+l+a+u+d+|e+n+c+u+l+e+|e+n+c+u+l+e{2,}|n+i+q+u+e+|n+i+q+u+e+r+|n+t+m+|f+d+p+|b+a+t+a+r+d+|p+e+t+a+s{2,}e+|c+h+a+t{2,}e+|z+o+b+|c+o+u+i+l{2,}e+|c+o+u+i+l{2,}e+s+|f+o+u+t+r+e+|t+a+p+e+t{2,}e+|g+o+u+i+n+e+|p+u+t+a+|p+u+t+o+|p+u+t+a+s+|p+u+t+o+s+|j+o+d+e+r+|c+o+n+o+|p+o+l{2,}a+|v+e+r+g+a+|z+o+r{2,}a+|c+u+l+o+|f+o+l{2,}a+r+|c+a+p+u+l{2,}o+|b+o+l+u+d+o+|p+a+j+e+r+o+|c+a+r+a+j+o+|m+a+r+i+c+a+|m+a+r+i+c+o+n+|c+a+b+r+o+n+|m+e+r+d+a+|c+o+l{2,}o+n+s+)(?:s|es)?$' or tok ~ 'f+u+c+k+|f+u+k+|m+o+t+h+e+r+f+u+c+k+|s+h+i+t+|b+u+l{2,}s+h+i+t+|b+i+t+c+h+|b+a+s+t+a+r+d+|a+s{2,}h+o+l+e+|a+r+s+e+h+o+l+e+|c+o+c+k+s+u+c+k+e+r+|b+l+o+w+j+o+b+|h+a+n+d+j+o+b+|j+e+r+k+o+f{2,}|d+u+m+b+a+s{2,}|d+i+c+k+h+e+a+d+|r+e+t+a+r+d+|n+i+g{2,}e+r+|n+i+g{2,}a+|n+i+g{2,}a+s+|f+a+g{2,}o+t+|h+i+t+l+e+r+|h+e+i+l+h+i+t+l+e+r+|p+o+r+n+h+u+b+|p+o+r+n+o+s+|w+h+o+r+e+h+o+u+s+e+|w+a+n+k+e+r+|b+o+l{2,}o+c+k+s+|p+u+s{2,}y+|p+u+t+a+i+n+|s+a+l+o+p+e+|s+a+l+a+u+d+|c+o+n{2,}a+r+d+|c+o+n{2,}a+s{2,}e+|e+n+c+u+l+e+|e+n+c+u+l+e+r+|m+e+r+d+e+|n+i+q+u+e+t+a+m+e+r+e+|n+i+k+t+a+m+e+r+|t+r+o+u+d+u+c+|t+r+o+u+d+c+u+l+|b+r+a+n+l+e+u+r+|b+r+a+n+l+e+t{2,}e+|b+o+u+g+n+o+u+l+|y+o+u+p+i+n+|p+e+t+a+s{2,}e+|c+o+u+i+l{2,}o+n+|f+i+l+s+d+e+p+u+t+e+|h+i+j+o+p+u+t+a+|h+i+j+o+d+e+p+u+t+a+|m+i+e+r+d+a+|g+i+l+i+p+o+l{2,}a+s+|g+i+l+i+p+o+l{2,}a+|p+e+n+d+e+j+o+|c+a+b+r+o+n+|c+h+i+n+g+a+d+a+|c+h+i+n+g+a+r+|c+h+i+n+g+a+|p+u+t+a+m+a+d+r+e+|s+u+d+a+c+a+|n+e+g+r+a+t+a+|m+a+m+a+h+u+e+v+o+|m+e+r+d+a+|c+o+l{2,}o+n+u+t+' then return 'bad'; end if;
  end loop;
  return '';
end $$;

create or replace function public.tpk_nick_ok(p text) returns boolean
language sql immutable set search_path = public as $$ select public.tpk_nick_check(p) = '' $$;

-- players: refuse a new or changed offensive name (names saved before this migration are shown as "Player" by the page)
create or replace function public.tpk_guard_players() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if length(coalesce(new.nick, '')) > 24 then raise exception 'bad_nick'; end if;
  if (tg_op = 'INSERT' or new.nick is distinct from old.nick) and not public.tpk_nick_ok(new.nick) then raise exception 'bad_nick'; end if;
  if new.ans is not null and octet_length(new.ans::text) > 20000 then raise exception 'too_big'; end if;
  if new.avatar is not null and length(new.avatar) > 100000 then raise exception 'too_big'; end if;
  if tg_op = 'INSERT' then
    if (select count(*) from players where code = new.code) >= 100 then raise exception 'room_full'; end if;
    if (select count(*) from players where created_at > now() - interval '1 hour') >= 6000 then raise exception 'slow_down'; end if;
  end if;
  return new;
end $$;

-- league: an offensive name becomes "Player"
create or replace function public.tpk_league_sync(p_pid text, p_nick text, p_xp int, p_country text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  cur text; r tpk_league_players; add int := least(greatest(coalesce(p_xp, 0), 0), 600);
  nm text := left(btrim(coalesce(p_nick, '')), 24); cc text := case when p_country ~ '^[A-Z]{2}$' then p_country else null end; rk int; n int; kk int; board jsonb;
begin
  if p_pid is null or p_pid !~ '^[A-Za-z0-9_-]{6,40}$' then raise exception 'bad id'; end if;
  if nm = '' or not public.tpk_nick_ok(nm) then nm := 'Player'; end if;
  cur := tpk_league_roll();
  insert into tpk_league_players (pid, nick, country, week, xp, total_xp) values (p_pid, nm, cc, cur, add, add)
  on conflict (pid) do update set nick = excluded.nick, country = excluded.country,
    xp = least(tpk_league_players.xp + add, 100000), total_xp = tpk_league_players.total_xp + add,
    updated_at = case when add > 0 then now() else tpk_league_players.updated_at end;
  select * into r from tpk_league_players where pid = p_pid;
  select count(*) into n from tpk_league_players where league = r.league and week = cur and xp > 0;
  select count(*) + 1 into rk from tpk_league_players
    where league = r.league and week = cur and xp > 0 and (xp > r.xp or (xp = r.xp and updated_at < r.updated_at));
  kk := case when n >= 3 then least(5, greatest(1, n / 5)) else 0 end;
  select coalesce(jsonb_agg(jsonb_build_object('nick', t.nick, 'country', t.country, 'xp', t.xp, 'me', t.pid = p_pid) order by t.xp desc, t.updated_at), '[]'::jsonb)
    into board from (select * from tpk_league_players where league = r.league and week = cur and xp > 0
                     order by xp desc, updated_at limit 30) t;
  return jsonb_build_object(
    'week', cur,
    'ends_at', (date_trunc('week', now() at time zone 'Europe/Paris') + interval '7 days') at time zone 'Europe/Paris',
    'league', r.league, 'xp', r.xp, 'rank', case when r.xp > 0 then rk else null end, 'n', n, 'up', kk,
    'down', case when n >= 5 and r.league > 0 then kk else 0 end,
    'board', board,
    'last', case when r.last_week is not null and r.last_week <> cur
                 then jsonb_build_object('week', r.last_week, 'from', r.last_from, 'to', r.last_to, 'rank', r.last_rank, 'n', r.last_n, 'xp', r.last_xp)
                 else null end);
end $$;

-- players already saved with an offensive name are renamed
update public.players set nick = 'Player' where not public.tpk_nick_ok(nick);
update public.tpk_league_players set nick = 'Player' where not public.tpk_nick_ok(nick);
